pruebas:
assert valida_edad("35") == 35, f"valida_edad('35') devolvió {valida_edad('35')!r}"
assert valida_edad("0") == 0 and valida_edad("120") == 120, "0 y 120 son válidos"
for malo in ["-1", "121", "200"]:
    try:
        valida_edad(malo)
    except ValueError as e:
        assert str(e) == "edad fuera de rango", f"mensaje para {malo!r}: {str(e)!r}"
    else:
        assert False, f"valida_edad({malo!r}) debía generar ValueError"
try:
    valida_edad("abc")
except ValueError:
    pass
else:
    assert False, "texto no numérico debe generar ValueError"

solucion:
def valida_edad(texto):
    edad = int(texto)
    if edad < 0 or edad > 120:
        raise ValueError("edad fuera de rango")
    return edad

